     1→import type { UploadFileAdapter } from "./upload-file";
     2→
     3→export const fileAdapter: UploadFileAdapter = {
     4→  uploadFile: async (params) => {
     5→    const file = params.file;
     6→    const reader = new FileReader();
     7→
     8→    return new Promise((resolve) => {
     9→      reader.onloadend = () => {
    10→        const base64String = reader.result as string;
    11→        resolve({ error: null, data: { url: base64String } });
    12→      };
    13→
    14→      reader.onerror = () => {
    15→        resolve({
    16→          error: new Error("Failed to convert file to base64"),
    17→          data: null,
    18→        });
    19→      };
    20→
    21→      reader.readAsDataURL(file);
    22→    });
    23→  },
    24→  uploadFiles: async (params) => {
    25→    const promises = params.map(async (param) => {
    26→      return new Promise<{ error: Error | null; data: { url: string } | null }>(
    27→        (resolve) => {
    28→          const reader = new FileReader();
    29→
    30→          reader.onloadend = () => {
    31→            const base64String = reader.result as string;
    32→            resolve({ error: null, data: { url: base64String } });
    33→          };
    34→
    35→          reader.onerror = () => {
    36→            resolve({
    37→              error: new Error("Failed to convert file to base64"),
    38→              data: null,
    39→            });
    40→          };
    41→
    42→          reader.readAsDataURL(param.file);
    43→        },
    44→      );
    45→    });
    46→
    47→    return Promise.all(promises);
    48→  },
    49→};
